using System.Collections.Concurrent;using AfriWallet.Fraud.DeviceRisk.Application.Abstractions;using AfriWallet.Fraud.DeviceRisk.Domain.Models;namespace AfriWallet.Fraud.DeviceRisk.Infrastructure;public sealed class InMemoryDeviceRiskRepository:IDeviceRiskRepository{private readonly ConcurrentDictionary<string,DeviceAccountRiskProfile> _profiles=new(StringComparer.OrdinalIgnoreCase);public Task SaveAsync(DeviceAccountRiskProfile p,CancellationToken ct=default){ct.ThrowIfCancellationRequested();_profiles[$"{p.Awid}|{p.DeviceId}"]=p;return Task.CompletedTask;}public Task<DeviceAccountRiskProfile?> GetLatestAsync(string awid,string device,CancellationToken ct=default){ct.ThrowIfCancellationRequested();_profiles.TryGetValue($"{awid}|{device}",out var p);return Task.FromResult(p);}}